alertmanagerIrcRelay.settings.example:
{
  http_host = "localhost";
  http_port = 8000;

  irc_host = "irc.example.com";
  irc_port = 7000;
  irc_nickname = "myalertbot";

  irc_channels = [
    { name = "#mychannel"; }
  ];
}

exporters.example:
{
  node = {
    enable = true;
    enabledCollectors = [ "systemd" ];
  };
  varnish.enable = true;
}

sachet.configuration.example:
{
  providers = {
    twilio = {
      # environment variables gets expanded at runtime
      account_sid = "$TWILIO_ACCOUNT";
      auth_token = "$TWILIO_TOKEN";
    };
  };
  templates = [ ./some-template.tmpl ];
  receivers = [{
    name = "pager";
    provider = "twilio";
    to = [ "+33123456789" ];
    text = "{{ template \"message\" . }}";
  }];
}
